// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.benchmark.common.ThemeQueryCatalog;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator.Theme;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.util.RDFInserter;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

/**
 * Full-size, engine-independent oracle for the denormalized Theme Q11 row counts. It is opt-in because some Q11
 * projections contain millions of distinct rows. Select themes with
 * {@code -Drdf4j.lmdb.themeQ11MemoryOracle.themes=LIBRARY,PHARMA}; omitting the selector checks every data theme.
 */
@EnabledIfSystemProperty(named = ThemeQueryQ11MemoryOracleTest.ENABLED_PROPERTY, matches = "(?i)true")
class ThemeQueryQ11MemoryOracleTest {

	static final String ENABLED_PROPERTY = "rdf4j.lmdb.themeQ11MemoryOracle.enabled";
	private static final String THEMES_PROPERTY = "rdf4j.lmdb.themeQ11MemoryOracle.themes";
	private static final int QUERY_INDEX = 11;

	@ParameterizedTest(name = "{0} Q11 catalog count matches MemoryStore")
	@EnumSource(value = Theme.class, names = { "ANALYTICS" }, mode = EnumSource.Mode.EXCLUDE)
	@Timeout(value = 15, unit = TimeUnit.MINUTES)
	void catalogCountMatchesMemoryStore(Theme theme) {
		assumeTrue(selectedThemes().contains(theme), () -> theme + " was not selected by " + THEMES_PROPERTY);

		SailRepository repository = new SailRepository(new MemoryStore());
		long actual;
		try (var connection = repository.getConnection()) {
			connection.begin();
			ThemeDataSetGenerator.generate(theme, new RDFInserter(connection));
			connection.commit();
			try (var result = connection.prepareTupleQuery(ThemeQueryCatalog.queryFor(theme, QUERY_INDEX)).evaluate()) {
				actual = result.stream().count();
			}
		} finally {
			repository.shutDown();
		}

		long catalogued = ThemeQueryCatalog.expectedCountFor(theme, QUERY_INDEX);
		System.err.println("[theme-q11-memory-oracle] theme=" + theme + ", rows=" + actual
				+ ", catalogued=" + catalogued);
		assertEquals(actual, catalogued,
				"Theme Q11 expected row count must come from the independent MemoryStore result");
	}

	private static Set<Theme> selectedThemes() {
		String configured = System.getProperty(THEMES_PROPERTY);
		if (configured == null || configured.isBlank()) {
			return EnumSet.complementOf(EnumSet.of(Theme.ANALYTICS));
		}
		return Arrays.stream(configured.split(","))
				.map(String::strip)
				.filter(value -> !value.isEmpty())
				.map(value -> Theme.valueOf(value.toUpperCase(Locale.ROOT)))
				.collect(Collectors.toCollection(() -> EnumSet.noneOf(Theme.class)));
	}
}
